using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;
using SimplePZMapmaker.Core;
using SimplePZMapmaker.Core.Export;
namespace SimplePZMapmaker.Web.Services;

[McpServerToolType]
public sealed class McpBuildingTools(AgentProjectStore sessions,GameAssetCatalog assets,StaticModelCatalog models) {
 [McpServerTool(Name="project_summary",ReadOnly=true,UseStructuredContent=true),Description("Read a browser-shared map session and its current revision. Every mutation must use that revision. Never guess sessionToken; the user copies it from Agent connection in the editor.")]
 public object Summary(string sessionToken){var s=sessions.Read(sessionToken);return new{s.Revision,s.Author,s.Updated,s.Project.Name,s.Project.Width,s.Project.Height,s.Project.WorldX,s.Project.WorldY,buildings=s.Project.Buildings.Select(b=>new{b.Id,b.Name,b.X,b.Y,b.Width,b.Height,minLevel=b.Design?.MinLevel,levels=b.Design?.Floors.Count}),dependencies=s.Project.RequiredMods};}
 [McpServerTool(Name="assets_search",ReadOnly=true,UseStructuredContent=true),Description("Search installed game and active mod sprites. Use assets_placement to get the complete canonical object before placing. Pagination limit at most72.")]
 public object AssetsSearch(string query="",string? category=null,int offset=0,int limit=36)=>assets.Search(query,category,offset,limit);
 [McpServerTool(Name="assets_placement",ReadOnly=true,UseStructuredContent=true),Description("Return canonical parts and physical flags of a game/mod sprite; do not invent sprite IDs or furniture dimensions.")]
 public object AssetPlacement(string id)=>assets.PlacementFor(id);
 [McpServerTool(Name="assets_pair",ReadOnly=true,UseStructuredContent=true),Description("Find matching north/west walls, doors or windows for a role, rather than rotating a single sprite arbitrarily.")]
 public object AssetPair(string id,string role)=>assets.Pair(id,role);
 [McpServerTool(Name="models_search",ReadOnly=true,UseStructuredContent=true),Description("Search registered static models from the installed game and enabled mods. Unsupported or missing resources are reported explicitly.")]
 public object ModelsSearch(string query="",int offset=0,int limit=36)=>models.Search(query,offset,limit);
 [McpServerTool(Name="models_placement",ReadOnly=true,UseStructuredContent=true),Description("Return verified model placement and source dependencies. Choose pickup/scenery/obstacle/destructible/container behavior explicitly; blocking profiles occupy one game tile.")]
 public object ModelPlacement(string id)=>models.Placement(id);
 [McpServerTool(Name="building_templates",ReadOnly=true,UseStructuredContent=true),Description("List original editable researched housing templates with dimensions, floors and basements.")]
 public object Templates()=>HousingTemplates.Catalog;
 [McpServerTool(Name="building_draft_create",UseStructuredContent=true),Description("Create an isolated draft from an existing map building, a catalog template, or a newly generated building. The map is unchanged until building_draft_commit.")]
 public AgentDraft CreateDraft(string sessionToken,string? buildingId=null,string? templateId=null,string name="Agent house",int width=16,int height=14,int levels=1,int basements=0,string shape="rect",int seed=42){
  Building b;if(buildingId is not null)b=sessions.Read(sessionToken).Project.Buildings.SingleOrDefault(b=>b.Id==buildingId)??throw new ArgumentException("Building not found.");
  else if(templateId is not null)b=HousingTemplates.Create(templateId);
  else{b=new(){Name=name,X=8,Y=8,Width=width,Height=height};b.Design=BuildingDesigner.Generate(b,levels,seed,shape,basements);}
  return sessions.SaveDraft(sessionToken,b);
 }
 [McpServerTool(Name="building_draft_read",ReadOnly=true,UseStructuredContent=true),Description("Read an isolated draft, including floor cells, rooms, walls, stairs and resources. Floor index is signed level minus minLevel.")]
 public AgentDraft ReadDraft(string sessionToken,string draftId)=>sessions.ReadDraft(sessionToken,draftId);
 [McpServerTool(Name="building_draft_object",UseStructuredContent=true),Description("Place a full canonical sprite object on an isolated floor. Multi-tile dimensions and flags come from the installed catalog. Stairs and access are checked before final commit.")]
 public AgentDraft PlaceDraftObject(string sessionToken,string draftId,int level,string assetId,int x,int y){var draft=sessions.ReadDraft(sessionToken,draftId);var f=Floor(draft.Building,level);var a=assets.PlacementFor(assetId);f.Objects.Add(new(){Kind="asset",X=x,Y=y,Asset=assetId,Parts=a.Parts.Select(part=>new BuildingObjects.Part(part.Dx,part.Dy,part.Tile,part.Flags)).ToList()});AssetRules.Building(draft.Building,assets,false);return sessions.SaveDraft(sessionToken,draft.Building,draftId);}
 [McpServerTool(Name="building_draft_replace",UseStructuredContent=true),Description("Replace an isolated draft with a complete Building JSON object. Structural/resource validation permits unfinished access, while commit/export require all rooms reachable and valid stairs. No map mutation.")]
 public AgentDraft ReplaceDraft(string sessionToken,string draftId,Building building){AssetRules.Building(building,assets,false);return sessions.SaveDraft(sessionToken,building,draftId);}
 [McpServerTool(Name="building_draft_room",UseStructuredContent=true),Description("Paint a rectangular room in an isolated floor. roomCode must already exist in floor.rooms, or '.' clears cells. Edges/furniture are not silently regenerated; inconsistent geometry is rejected atomically.")]
 public AgentDraft PaintRoom(string sessionToken,string draftId,int level,int x,int y,int width,int height,string roomCode){var draft=sessions.ReadDraft(sessionToken,draftId);var b=draft.Building;var f=Floor(b,level);if(roomCode.Length!=1||roomCode!="."&&!f.Rooms.ContainsKey(roomCode)||x<0||y<0||width<1||height<1||x+width>b.Width||y+height>b.Height)throw new ArgumentException("Invalid room region.");var cells=f.Cells.ToCharArray();for(var yy=y;yy<y+height;yy++)for(var xx=x;xx<x+width;xx++)cells[yy*b.Width+xx]=roomCode[0];f.Cells=new(cells);AssetRules.Building(b,assets,false);return sessions.SaveDraft(sessionToken,b,draftId);}
 [McpServerTool(Name="building_draft_edge",UseStructuredContent=true),Description("Set one N/W wall, door, window or open edge. Incompatible previous resources are cleared. Provide real direction-compatible wallTile/openingTile from assets_pair.")]
 public AgentDraft SetEdge(string sessionToken,string draftId,int level,int x,int y,string direction,string kind,string? wallTile=null,string? openingTile=null){var draft=sessions.ReadDraft(sessionToken,draftId);var f=Floor(draft.Building,level);f.Edges.RemoveAll(e=>e.X==x&&e.Y==y&&e.Edge==direction);f.Edges.Add(new(){X=x,Y=y,Edge=direction,Kind=kind,WallTile=wallTile,OpeningTile=openingTile,Edited=true});AssetRules.Building(draft.Building,assets,false);return sessions.SaveDraft(sessionToken,draft.Building,draftId);}
 [McpServerTool(Name="building_draft_validate",ReadOnly=true,UseStructuredContent=true),Description("Check complete building access, stairs, source resources and static models before commit. Validation does not publish a draft.")]
 public object ValidateDraft(string sessionToken,string draftId){var b=sessions.ReadDraft(sessionToken,draftId).Building;AssetRules.Building(b,assets);foreach(var m in b.Design?.Floors.SelectMany(f=>f.StaticModels)??[])models.Validate(m);return new{valid=true};}
 [McpServerTool(Name="building_draft_preview",ReadOnly=true,UseStructuredContent=true),Description("Return the actual native composed sprite scene of an unfinished draft. Signed level null means all floors. Sprite pages are exposed via /api/assets/page; no synthetic thumbnails.")]
 public object PreviewDraft(string sessionToken,string draftId,int? level=null){var b=sessions.ReadDraft(sessionToken,draftId).Building;AssetRules.Building(b,assets,false);return NativeScene.DraftBuilding(b,level);}
 [McpServerTool(Name="building_draft_commit",UseStructuredContent=true),Description("Commit an isolated draft to the map or template library against expectedRevision. x/y are map tile coordinates. targetBuildingId replaces only that existing building. Invalid geometry or stale revision leaves map unchanged. Browser imports this revision as one undoable action.")]
 public object CommitDraft(string sessionToken,string draftId,long expectedRevision,int x,int y,string? targetBuildingId=null,bool library=false){var b=sessions.ReadDraft(sessionToken,draftId).Building;AssetRules.Building(b,assets);return Mutation(sessionToken,expectedRevision,p=>{b.X=x;b.Y=y;b.Modified=true;b.LevelsOrigin="manual";if(library){b.Id=Guid.NewGuid().ToString("N");p.BuildingLibrary.Add(b);}else if(targetBuildingId is null){b.Id=Guid.NewGuid().ToString("N");p.Buildings.Add(b);}else{var i=p.Buildings.FindIndex(a=>a.Id==targetBuildingId);if(i<0)throw new ArgumentException("The original building no longer exists.");b.Id=targetBuildingId;p.Buildings[i]=b;}p.Version=Math.Max(p.Version,6);});}
 [McpServerTool(Name="environment_place_sprite",UseStructuredContent=true),Description("Place one complete installed sprite object in the environment. Uses actual canonical SpriteGrid parts and flags. Rejects overlap, water, buildings and spawns atomically.")]
 public object PlaceSprite(string sessionToken,long expectedRevision,string assetId,int x,int y){var asset=assets.PlacementFor(assetId);return Mutation(sessionToken,expectedRevision,p=>{p.Decorations.Add(new(){X=x,Y=y,Asset=assetId,Parts=asset.Parts.Select(part=>new BuildingObjects.Part(part.Dx,part.Dy,part.Tile,part.Flags)).ToList()});p.Version=Math.Max(6,p.Version);});}
 [McpServerTool(Name="environment_place_model",UseStructuredContent=true),Description("Place an installed static world item model on ground against a revision. Actual mesh/textures remain in the owning game/mod; export references its dependencies.")]
 public object PlaceModel(string sessionToken,long expectedRevision,string modelId,int x,int y,double rotation=0,double scale=1,string profile="pickup",int health=500,int capacity=50){var model=models.Placement(modelId);model.X=x;model.Y=y;model.Rotation=rotation;model.Scale=scale;model.Profile=profile;model.Health=health;model.Capacity=capacity;return Mutation(sessionToken,expectedRevision,p=>{p.StaticModels.Add(model);p.Version=Math.Max(6,p.Version);});}
 [McpServerTool(Name="environment_paint",UseStructuredContent=true),Description("Paint at most128x128 tiles of ground type (0 grass,1 forest,2 road,3 water,4 sand,5 dirt,6 pavement). Clears previous explicit surface tiles. Occupied objects/spawns prevent invalid water placement.")]
 public object PaintTerrain(string sessionToken,long expectedRevision,int x,int y,int width,int height,int terrain){return Mutation(sessionToken,expectedRevision,p=>{if(x<0||y<0||width is <1 or >128||height is <1 or >128||x+width>p.Width||y+height>p.Height||terrain is <0 or >6)throw new ArgumentException("Invalid terrain region.");var mask=TerrainEditMask.Decode(p);for(var yy=y;yy<y+height;yy++)for(var xx=x;xx<x+width;xx++){var index=yy*p.Width+xx;p.Terrain[index]=(Terrain)terrain;p.SurfaceTiles.Remove(index);mask[index/8]|=(byte)(1<<(index%8));}p.TerrainEdits=TerrainEditMask.Encode(mask);p.Version=Math.Max(6,p.Version);});}
 [McpServerTool(Name="project_remove_object",Destructive=true,UseStructuredContent=true),Description("Remove a selected building, environment sprite, or static model by exact ID. Revision protected and undoable after browser synchronization.")]
 public object Remove(string sessionToken,long expectedRevision,string id)=>Mutation(sessionToken,expectedRevision,p=>{if(p.Buildings.RemoveAll(b=>b.Id==id)+p.Decorations.RemoveAll(d=>d.Id==id)+p.StaticModels.RemoveAll(m=>m.Id==id)==0)throw new ArgumentException("Object not found.");});
 [McpServerTool(Name="project_export",ReadOnly=true,UseStructuredContent=true),Description("Validate and export the current session as a native Build42 mod ZIP inside the project workspace. No automatic installation into the game. Returns an editor download URL.")]
 public object Export(string sessionToken,long expectedRevision){var s=sessions.Read(sessionToken);if(s.Revision!=expectedRevision)throw new AgentRevisionConflict(s.Revision);AssetRules.Project(s.Project,assets);models.Validate(s.Project);var bytes=NativeMapExporter.Export(s.Project);return new{revision=s.Revision,bytes=bytes.Length,downloadUrl=$"/api/agent/export/{sessionToken}/{s.Revision}"};}
 object Mutation(string token,long revision,Action<MapProject> action){var s=sessions.Mutate(token,revision,p=>{action(p);AssetRules.Project(p,assets);models.Validate(p);},"agent");return new{s.Revision,s.Author,s.Updated};}
 static BuildingFloor Floor(Building b,int level){var d=b.Design??throw new ArgumentException("The building has no floor plan.");var index=level-d.MinLevel;if(index<0||index>=d.Floors.Count)throw new ArgumentException("Level does not exist.");return d.Floors[index];}
}
